// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetLiveness Process is up (no dependency checks)
	// (GET /healthz)
	GetLiveness(w http.ResponseWriter, r *http.Request)
	// GetReadiness Dependencies usable
	// (GET /readyz)
	GetReadiness(w http.ResponseWriter, r *http.Request)
	// GetPublicReleases A workspace's published release notes (no sign-in)
	// (GET /v1/public/releases/{slug})
	GetPublicReleases(w http.ResponseWriter, r *http.Request, slug string, params GetPublicReleasesParams)
	// GetPublicRelease One published release note (no sign-in)
	// (GET /v1/public/releases/{slug}/{noteId})
	GetPublicRelease(w http.ResponseWriter, r *http.Request, slug string, noteId NoteId)
	// CheckUnsubscribe Check an unsubscribe link before confirming (no sign-in)
	// (GET /v1/public/unsubscribe/{token})
	CheckUnsubscribe(w http.ResponseWriter, r *http.Request, token UnsubscribeToken)
	// ConfirmUnsubscribe Stop all further email to this address from this workspace (no sign-in)
	// (POST /v1/public/unsubscribe/{token})
	ConfirmUnsubscribe(w http.ResponseWriter, r *http.Request, token UnsubscribeToken)
	// ListWorkspaces Workspaces the signed-in user belongs to
	// (GET /v1/workspaces)
	ListWorkspaces(w http.ResponseWriter, r *http.Request)
	// CreateWorkspace Create a workspace; the caller becomes its admin
	// (POST /v1/workspaces)
	CreateWorkspace(w http.ResponseWriter, r *http.Request)
	// ListAccounts Accounts (customer companies), A to Z
	// (GET /v1/workspaces/{workspaceId}/accounts)
	ListAccounts(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, params ListAccountsParams)
	// CreateAccount Add an account
	// (POST /v1/workspaces/{workspaceId}/accounts)
	CreateAccount(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// UpdateAccount Replace an account's details
	// (PUT /v1/workspaces/{workspaceId}/accounts/{accountId})
	UpdateAccount(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, accountId openapi_types.UUID)
	// ExportWorkspace Download everything in the workspace as JSON (admins only)
	// (GET /v1/workspaces/{workspaceId}/export)
	ExportWorkspace(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// AcceptHighlightSuggestion Turn a suggestion into a highlight, optionally with your own tags
	// (POST /v1/workspaces/{workspaceId}/highlight-suggestions/{suggestionId}/accept)
	AcceptHighlightSuggestion(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, suggestionId SuggestionId)
	// DismissHighlightSuggestion Throw a suggestion away
	// (POST /v1/workspaces/{workspaceId}/highlight-suggestions/{suggestionId}/dismiss)
	DismissHighlightSuggestion(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, suggestionId SuggestionId)
	// ListHighlights Highlights, newest first, optionally for one tag or one source
	// (GET /v1/workspaces/{workspaceId}/highlights)
	ListHighlights(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, params ListHighlightsParams)
	// CreateHighlight Mark a passage of a source. The text must match the source at those byte offsets exactly.
	// (POST /v1/workspaces/{workspaceId}/highlights)
	CreateHighlight(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// DeleteHighlight Remove a highlight
	// (DELETE /v1/workspaces/{workspaceId}/highlights/{highlightId})
	DeleteHighlight(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, highlightId HighlightId)
	// SetHighlightTags Replace the tags on a highlight
	// (PUT /v1/workspaces/{workspaceId}/highlights/{highlightId}/tags)
	SetHighlightTags(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, highlightId HighlightId)
	// ListMedia Recent recordings and uploads in progress
	// (GET /v1/workspaces/{workspaceId}/media)
	ListMedia(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// StartUpload Begin a resumable upload of a recording. Send the bytes in chunks, then complete it.
	// (POST /v1/workspaces/{workspaceId}/media)
	StartUpload(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// DeleteMedia Delete a recording, its transcript and everything built on it
	// (DELETE /v1/workspaces/{workspaceId}/media/{mediaId})
	DeleteMedia(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, mediaId MediaId)
	// GetMedia A recording's state; for an unfinished upload, where to continue
	// (GET /v1/workspaces/{workspaceId}/media/{mediaId})
	GetMedia(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, mediaId MediaId)
	// UploadChunk Send the next piece of the file. The offset must equal the bytes already received.
	// (PUT /v1/workspaces/{workspaceId}/media/{mediaId}/chunk)
	UploadChunk(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, mediaId MediaId, params UploadChunkParams)
	// CompleteUpload Finish the upload and start the transcription
	// (POST /v1/workspaces/{workspaceId}/media/{mediaId}/complete)
	CompleteUpload(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, mediaId MediaId)
	// GetMediaFile The recording itself, for the player. Supports a single byte range.
	// (GET /v1/workspaces/{workspaceId}/media/{mediaId}/file)
	GetMediaFile(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, mediaId MediaId, params GetMediaFileParams)
	// ListOutreach Batches of personal messages waiting for review, or already sent
	// (GET /v1/workspaces/{workspaceId}/outreach)
	ListOutreach(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, params ListOutreachParams)
	// EditOutreachMessage Change a draft before approving it
	// (PUT /v1/workspaces/{workspaceId}/outreach/messages/{messageId})
	EditOutreachMessage(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, messageId MessageId)
	// ExcludeOutreachMessage Leave this person out of the batch
	// (POST /v1/workspaces/{workspaceId}/outreach/messages/{messageId}/exclude)
	ExcludeOutreachMessage(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, messageId MessageId)
	// IncludeOutreachMessage Put an excluded person back in the batch
	// (POST /v1/workspaces/{workspaceId}/outreach/messages/{messageId}/include)
	IncludeOutreachMessage(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, messageId MessageId)
	// RetryOutreachMessage Try again to send a message that failed
	// (POST /v1/workspaces/{workspaceId}/outreach/messages/{messageId}/retry)
	RetryOutreachMessage(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, messageId MessageId)
	// GetOutreachBatch One batch with every message and the words each is based on
	// (GET /v1/workspaces/{workspaceId}/outreach/{batchId})
	GetOutreachBatch(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, batchId BatchId)
	// ApproveOutreachBatch Approve every message still marked as a draft and queue them to be sent
	// (POST /v1/workspaces/{workspaceId}/outreach/{batchId}/approve)
	ApproveOutreachBatch(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, batchId BatchId)
	// CancelOutreachBatch Withdraw a batch that has not been approved
	// (POST /v1/workspaces/{workspaceId}/outreach/{batchId}/cancel)
	CancelOutreachBatch(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, batchId BatchId)
	// ListPeople People, A to Z
	// (GET /v1/workspaces/{workspaceId}/people)
	ListPeople(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, params ListPeopleParams)
	// CreatePerson Add a person
	// (POST /v1/workspaces/{workspaceId}/people)
	CreatePerson(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// ImportPeople Import people and accounts from a CSV, all or nothing
	// (POST /v1/workspaces/{workspaceId}/people/import)
	ImportPeople(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// PreviewPeopleImport Read a CSV and show what would be imported; writes nothing
	// (POST /v1/workspaces/{workspaceId}/people/import/preview)
	PreviewPeopleImport(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// DeletePerson Delete a person with their quotes, conversations, recordings and the messages written to them. Their opt-out is kept. (admins only)
	// (DELETE /v1/workspaces/{workspaceId}/people/{personId})
	DeletePerson(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, personId openapi_types.UUID)
	// UpdatePerson Replace a person's details
	// (PUT /v1/workspaces/{workspaceId}/people/{personId})
	UpdatePerson(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, personId openapi_types.UUID)
	// ListProposals The review queue
	// (GET /v1/workspaces/{workspaceId}/proposals)
	ListProposals(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, params ListProposalsParams)
	// BulkAcceptProposals Accept every suggestion at or above a confidence threshold
	// (POST /v1/workspaces/{workspaceId}/proposals/bulk-accept)
	BulkAcceptProposals(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// RenameProposal Change the proposed title before accepting
	// (PATCH /v1/workspaces/{workspaceId}/proposals/{proposalId})
	RenameProposal(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, proposalId ProposalId)
	// AcceptProposal Turn a suggestion into a request (or add it to an existing one) with cited evidence
	// (POST /v1/workspaces/{workspaceId}/proposals/{proposalId}/accept)
	AcceptProposal(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, proposalId ProposalId)
	// DismissProposal Dismiss a suggestion
	// (POST /v1/workspaces/{workspaceId}/proposals/{proposalId}/dismiss)
	DismissProposal(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, proposalId ProposalId)
	// UndoProposal Put an accepted or dismissed suggestion back in the queue
	// (POST /v1/workspaces/{workspaceId}/proposals/{proposalId}/undo)
	UndoProposal(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, proposalId ProposalId)
	// ListAnswers Your recent questions and the answers you got
	// (GET /v1/workspaces/{workspaceId}/qa)
	ListAnswers(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// AskQuestion Ask a question about what customers said. The answer cites stored quotes, or says there is not enough evidence.
	// (POST /v1/workspaces/{workspaceId}/qa)
	AskQuestion(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// GetAnswer One answer with its citations
	// (GET /v1/workspaces/{workspaceId}/qa/{answerId})
	GetAnswer(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, answerId AnswerId)
	// RateAnswer Say whether an answer was good or wrong
	// (PUT /v1/workspaces/{workspaceId}/qa/{answerId}/rating)
	RateAnswer(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, answerId AnswerId)
	// GetQuality How often the machine's suggestions are right, from what people did with them, and what the AI costs
	// (GET /v1/workspaces/{workspaceId}/quality)
	GetQuality(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, params GetQualityParams)
	// ListReleaseNotes Release notes, newest first
	// (GET /v1/workspaces/{workspaceId}/release-notes)
	ListReleaseNotes(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, params ListReleaseNotesParams)
	// CreateReleaseNote Start a release note (a draft)
	// (POST /v1/workspaces/{workspaceId}/release-notes)
	CreateReleaseNote(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// GetReleaseNote One release note with the requests it closes
	// (GET /v1/workspaces/{workspaceId}/release-notes/{noteId})
	GetReleaseNote(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, noteId NoteId)
	// UpdateReleaseNote Change a release note's title or text
	// (PUT /v1/workspaces/{workspaceId}/release-notes/{noteId})
	UpdateReleaseNote(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, noteId NoteId)
	// PublishReleaseNote Publish now, or at a chosen moment (an absolute time, so time zones cannot move it)
	// (POST /v1/workspaces/{workspaceId}/release-notes/{noteId}/publish)
	PublishReleaseNote(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, noteId NoteId)
	// SetReleaseNoteRequests Choose which requests this note closes
	// (PUT /v1/workspaces/{workspaceId}/release-notes/{noteId}/requests)
	SetReleaseNoteRequests(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, noteId NoteId)
	// UnpublishReleaseNote Take a note off the public page
	// (POST /v1/workspaces/{workspaceId}/release-notes/{noteId}/unpublish)
	UnpublishReleaseNote(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, noteId NoteId)
	// ListRequests Requests, newest first
	// (GET /v1/workspaces/{workspaceId}/requests)
	ListRequests(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, params ListRequestsParams)
	// GetRequest One request with its cited evidence
	// (GET /v1/workspaces/{workspaceId}/requests/{requestId})
	GetRequest(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, requestId openapi_types.UUID)
	// GetBrief The decision brief for a request, with freshly computed facts
	// (GET /v1/workspaces/{workspaceId}/requests/{requestId}/brief)
	GetBrief(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, requestId RequestId)
	// RequestBrief Write (or refresh) the brief; does nothing if the current one is up to date
	// (POST /v1/workspaces/{workspaceId}/requests/{requestId}/brief)
	RequestBrief(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, requestId RequestId)
	// SetRequestStatus Change a request's status. Moving it to a shipped status prepares personal messages for the people who asked; nothing is sent until a person approves them.
	// (PUT /v1/workspaces/{workspaceId}/requests/{requestId}/status)
	SetRequestStatus(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, requestId RequestId)
	// SetRequestTags Replace the tags on a request
	// (PUT /v1/workspaces/{workspaceId}/requests/{requestId}/tags)
	SetRequestTags(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, requestId RequestId)
	// GetWorkspaceSettings Public address of the release page and the name that signs messages
	// (GET /v1/workspaces/{workspaceId}/settings)
	GetWorkspaceSettings(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// UpdateWorkspaceSettings Change the public address or the sender name (admins only)
	// (PUT /v1/workspaces/{workspaceId}/settings)
	UpdateWorkspaceSettings(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// IngestPaste Paste a conversation; extraction runs in the background
	// (POST /v1/workspaces/{workspaceId}/sources/paste)
	IngestPaste(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// DeleteSource Delete a conversation or recording with every quote, highlight, transcript and file built on it (admins only)
	// (DELETE /v1/workspaces/{workspaceId}/sources/{sourceItemId})
	DeleteSource(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, sourceItemId openapi_types.UUID)
	// GetSource A stored source with its processing state and full text
	// (GET /v1/workspaces/{workspaceId}/sources/{sourceItemId})
	GetSource(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, sourceItemId openapi_types.UUID)
	// ListHighlightSuggestions Passages the assistant suggests highlighting, using your tags
	// (GET /v1/workspaces/{workspaceId}/sources/{sourceItemId}/highlight-suggestions)
	ListHighlightSuggestions(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, sourceItemId openapi_types.UUID)
	// RequestHighlightSuggestions Ask the assistant to suggest highlights. Nothing is highlighted until you accept it.
	// (POST /v1/workspaces/{workspaceId}/sources/{sourceItemId}/highlight-suggestions)
	RequestHighlightSuggestions(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, sourceItemId openapi_types.UUID)
	// GetTranscript The timed segments of a recording's transcript
	// (GET /v1/workspaces/{workspaceId}/sources/{sourceItemId}/transcript)
	GetTranscript(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, sourceItemId openapi_types.UUID)
	// ListStatuses The statuses a request can have
	// (GET /v1/workspaces/{workspaceId}/statuses)
	ListStatuses(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// CreateStatus Add a status (admins only)
	// (POST /v1/workspaces/{workspaceId}/statuses)
	CreateStatus(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// RenameStatus Rename a status (admins only)
	// (PUT /v1/workspaces/{workspaceId}/statuses/{statusId})
	RenameStatus(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, statusId openapi_types.UUID)
	// UndoTagMerge Put a merged tag back exactly as it was (admins only)
	// (POST /v1/workspaces/{workspaceId}/tag-merges/{mergeId}/undo)
	UndoTagMerge(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, mergeId openapi_types.UUID)
	// ListTags The codebook, with how many highlights and requests use each tag
	// (GET /v1/workspaces/{workspaceId}/tags)
	ListTags(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, params ListTagsParams)
	// CreateTag Add a tag to the codebook
	// (POST /v1/workspaces/{workspaceId}/tags)
	CreateTag(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// UpdateTag Change a tag's name, definition or colour
	// (PUT /v1/workspaces/{workspaceId}/tags/{tagId})
	UpdateTag(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, tagId TagId)
	// ArchiveTag Hide a tag from pickers without changing what it is applied to (admins only)
	// (POST /v1/workspaces/{workspaceId}/tags/{tagId}/archive)
	ArchiveTag(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, tagId TagId)
	// MergeTag Move everything with this tag onto another tag and archive this one (admins only). It can be undone.
	// (POST /v1/workspaces/{workspaceId}/tags/{tagId}/merge)
	MergeTag(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, tagId TagId)
	// RestoreTag Bring an archived tag back (admins only)
	// (POST /v1/workspaces/{workspaceId}/tags/{tagId}/restore)
	RestoreTag(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, tagId TagId)
	// ListViews Saved views of the request list, shared by the workspace
	// (GET /v1/workspaces/{workspaceId}/views)
	ListViews(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// CreateView Save the current filters and order under a name
	// (POST /v1/workspaces/{workspaceId}/views)
	CreateView(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// DeleteView Remove a saved view (its creator or an admin)
	// (DELETE /v1/workspaces/{workspaceId}/views/{viewId})
	DeleteView(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, viewId openapi_types.UUID)
}

